import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import './features/index.ts';
import { App } from './app-shell/App.tsx';
import './shared-ui/styles.css';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

// Offline support: only in production builds (dist/sw.js is generated by scripts/build.mjs).
if ('serviceWorker' in navigator && __PROD__ && (location.protocol === 'https:' || location.hostname === 'localhost')) {
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('./sw.js').catch(() => {
      /* offline cache is optional */
    });
  });
}
